# Edited by Cursor (rapidfuzz cdist, precompute by length)
"""Scan for words with exactly one digit that are 1 edit from another word in the same transcript."""

import re
from collections import defaultdict

from rapidfuzz import process
from rapidfuzz.distance import Levenshtein

WORD_RE = re.compile(r"\w+")


def _token_has_single_digit(token: str) -> bool:
    """Return True if token contains exactly one digit."""
    return sum(1 for c in token if c.isdigit()) == 1


def scan_turn_typo_levenshtein(
    text: str,
    path_str: str,
    transcript_words: set[str],
) -> list[tuple[str, int, str, str, str]]:
    """Emit (typo_levenshtein, ...) when token has one digit and exactly one 1-Levenshtein match. Precomputes choices by length to avoid scanning full word list per token."""
    result: list[tuple[str, int, str, str, str]] = []
    tokens_with_digit = [
        (m.start(), m.group(0))
        for m in WORD_RE.finditer(text)
        if _token_has_single_digit(m.group(0))
    ]
    if not tokens_with_digit:
        return result
    by_len: dict[int, list[str]] = defaultdict(list)
    for w in transcript_words:
        by_len[len(w)].append(w)
    for start, token in tokens_with_digit:
        ln = len(token)
        candidates = [
            w
            for w in (
                by_len.get(ln - 1, []) + by_len.get(ln, []) + by_len.get(ln + 1, [])
            )
            if w != token
        ]
        if not candidates:
            continue
        matches = process.extract(
            token,
            candidates,
            scorer=Levenshtein.distance,
            score_cutoff=1,
            limit=3,
        )
        dist1 = [m for m in matches if m[1] == 1]
        if len(dist1) == 1:
            result.append(
                (
                    "typo_levenshtein",
                    start,
                    token,
                    path_str,
                    dist1[0][0],
                )
            )
    return result
